<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content publishx-scope"><div class="tw-flex tw-justify-between"><h3><?php echo _l('publishx_websites'); ?></h3><a class="btn btn-primary" href="<?php echo admin_url('publishx/website'); ?>"><i class="fa fa-plus"></i> Add Website</a></div><div class="panel_s"><div class="panel-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Name</th><th>URL</th><th>Default folder</th><th>Method</th><th>Active</th><th>Actions</th></tr></thead><tbody><?php foreach($websites as $w){?><tr><td><?php echo html_escape($w['name']); ?></td><td><a target="_blank" href="<?php echo html_escape($w['base_url']); ?>"><?php echo html_escape($w['base_url']); ?></a></td><td><?php echo html_escape($w['default_folder']); ?></td><td><?php echo html_escape($w['publish_method']); ?></td><td><?php echo $w['active']?'Yes':'No'; ?></td><td><a target="_blank" class="btn btn-info btn-xs" href="<?php echo html_escape($w['base_url']); ?>"><i class="fa fa-eye"></i> View</a> <a class="btn btn-warning btn-xs" href="<?php echo admin_url('publishx/test_website/'.$w['id']); ?>"><i class="fa fa-vial"></i> Test</a> <a class="btn btn-default btn-xs" href="<?php echo admin_url('publishx/website/'.$w['id']); ?>"><i class="fa fa-edit"></i></a> <a class="btn btn-danger btn-xs _delete" href="<?php echo admin_url('publishx/delete_website/'.$w['id']); ?>"><i class="fa fa-trash"></i></a></td></tr><?php }?></tbody></table></div></div></div></div></div><?php init_tail(); ?></body></html>